#!/usr/bin/env node

/**
 * The fallback share card.
 *
 * Every page must emit a valid `og:image`, and the real artwork (`OG-01` in
 * `docs/visuals/prompts/04-og-images.md`) is generated by hand and may land
 * weeks from now. So this composes an austere but genuinely on-brand card from
 * assets we already have: the lockup on Night, the fique rule, the domain.
 *
 * ## The guard is the important part
 *
 * This runs in `prebuild`, on every build, forever. The day the real artwork is
 * dropped at the same path, a generator that overwrites would silently replace
 * it — and nobody would notice, because the fallback also looks fine. So the
 * generator refuses to write over a file it did not itself produce.
 *
 * It recognises its own output by a marker written into the file's EXIF
 * description, not by a filename or a date: a hand-generated card copied over
 * the fallback keeps the same name, and modification times survive nothing. The
 * marker is the only signal that travels with the bytes.
 *
 * `tests/unit/scripts/og-fallback.test.ts` covers the guard directly, because
 * "does not destroy the designer's work" is not a property to verify by hand.
 *
 * Usage:
 *   node scripts/generate-og-fallback.mjs           # generate if absent
 *   node scripts/generate-og-fallback.mjs --force   # regenerate the fallback
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import sharp from 'sharp';

const ROOT = process.cwd();

/**
 * Written into the EXIF description of every generated fallback.
 *
 * Anything carrying this string is ours to overwrite; anything without it is
 * somebody's artwork and is left alone.
 */
export const FALLBACK_MARKER = 'cabuya-og-fallback';

export const CARD_WIDTH = 1200;
export const CARD_HEIGHT = 630;

const NIGHT = '#082a24';
const IVORY = '#f6f3ed';
const FIQUE = '#c79a4a';

/** The cards this script is responsible for. */
export const CARDS = [
  {
    path: 'public/images/og-default-en.jpg',
    line: 'The open aid interoperability protocol',
  },
  {
    path: 'public/images/og-default.jpg',
    line: 'El protocolo abierto de interoperabilidad para ayuda',
  },
];

/**
 * May this file be written?
 *
 * `true` when it does not exist, or when it exists and is a previously
 * generated fallback. `false` when it exists and carries no marker — that is
 * either the real artwork or something a human put there deliberately, and
 * either way it is not ours.
 */
export function mayWrite(buffer) {
  if (buffer === null || buffer === undefined) return true;
  return buffer.includes(FALLBACK_MARKER);
}

/** Read a file if present; `null` when absent. */
function readIfPresent(absolutePath) {
  return existsSync(absolutePath) ? readFileSync(absolutePath) : null;
}

async function generate(card) {
  const lockup = await sharp(
    join(ROOT, 'public/images/brand/cabuya-lockup-dark.png')
  )
    .resize(420, Math.round((420 * 213) / 640))
    .toBuffer();

  const canvas = Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${CARD_WIDTH}" height="${CARD_HEIGHT}">
       <rect width="${CARD_WIDTH}" height="${CARD_HEIGHT}" fill="${NIGHT}"/>
       <rect x="0" y="${CARD_HEIGHT - 10}" width="${CARD_WIDTH}" height="10" fill="${FIQUE}"/>
       <text x="90" y="${CARD_HEIGHT / 2 + 96}" font-family="Poppins, Helvetica, Arial, sans-serif"
             font-size="40" fill="${IVORY}">${card.line}</text>
       <text x="90" y="${CARD_HEIGHT / 2 + 156}" font-family="Poppins, Helvetica, Arial, sans-serif"
             font-size="28" fill="${FIQUE}">cabuya.org</text>
     </svg>`
  );

  return sharp(canvas)
    .composite([{ input: lockup, left: 86, top: 150 }])
    .jpeg({ quality: 88 })
    .withExif({ IFD0: { ImageDescription: FALLBACK_MARKER } })
    .toBuffer();
}

async function main() {
  const force = process.argv.includes('--force');
  let wrote = 0;
  let kept = 0;

  for (const card of CARDS) {
    const absolutePath = join(ROOT, card.path);
    const existing = readIfPresent(absolutePath);

    if (existing && !mayWrite(existing)) {
      // Not ours. `--force` deliberately does not override this: the flag is
      // for regenerating the fallback, never for discarding real artwork.
      console.log(
        `  ⏭  ${card.path} — not a generated fallback, left untouched`
      );
      kept += 1;
      continue;
    }
    if (existing && !force) {
      // Already ours and already correct; regenerating every build would churn
      // the file and its hash for nothing.
      kept += 1;
      continue;
    }

    // Write the encoded bytes directly. Passing the buffer back through sharp
    // would re-encode it and strip the very marker the guard depends on.
    writeFileSync(absolutePath, await generate(card));
    console.log(`  ✓ ${card.path} — fallback card written`);
    wrote += 1;
  }

  if (wrote === 0) {
    console.log(`[og-fallback] ${kept} card(s) already in place`);
  }
}

// Only run when invoked directly, so the test can import the guard.
if (process.argv[1]?.endsWith('generate-og-fallback.mjs')) {
  await main();
}
